function frMandelPoint(cr, ci, maxIter){
  var zr=0, zi=0, i=0;
  while(i<maxIter){
    var r2=zr*zr, i2=zi*zi;
    if(r2+i2>4) return i;
    zi=2*zr*zi+ci; zr=r2-i2+cr; i++;
  }
  return maxIter;
}
function frMandelGrid(w, h, maxIter){
  if(!Number.isInteger(w)||!Number.isInteger(h)||w<8||h<8||w>200||h>200)
    return { value:null, error:'网格须为 8-200 的整数' };
  var mi=maxIter||40, rows=[];
  for(var y=0;y<h;y++){
    var row=[];
    for(var x=0;x<w;x++){
      var cr=-2.2+(x/(w-1))*3.0, ci=-1.3+(y/(h-1))*2.6;
      row.push(frMandelPoint(cr, ci, mi));
    }
    rows.push(row);
  }
  return { value:rows, error:null };
}
function frKoch(order){
  if(!Number.isInteger(order)||order<0||order>6) return { value:null, error:'阶数须为 0-6 整数' };
  var s=420, hgt=s*Math.sqrt(3)/2;
  var pts=[[60,110+hgt*0.75],[60+s,110+hgt*0.75],[60+s/2,110+hgt*0.75-hgt]];
  var segs=[[pts[0],pts[1]],[pts[1],pts[2]],[pts[2],pts[0]]];
  for(var o=0;o<order;o++){
    var next=[];
    for(var i=0;i<segs.length;i++){
      var a=segs[i][0], b=segs[i][1];
      var dx=(b[0]-a[0])/3, dy=(b[1]-a[1])/3;
      var p1=[a[0]+dx, a[1]+dy], p2=[a[0]+2*dx, a[1]+2*dy];
      var ang=Math.atan2(dy,dx)-Math.PI/3, len=Math.sqrt(dx*dx+dy*dy);
      var peak=[p1[0]+Math.cos(ang)*len, p1[1]+Math.sin(ang)*len];
      next.push([a,p1],[p1,peak],[peak,p2],[p2,b]);
    }
    segs=next;
  }
  return { value:segs, error:null };
}
function frSierpinski(order){
  if(!Number.isInteger(order)||order<0||order>7) return { value:null, error:'阶数须为 0-7 整数' };
  var tris=[[[270,20],[40,420],[500,420]]], out=[];
  for(var o=0;o<order;o++){
    var next=[];
    for(var i=0;i<tris.length;i++){
      var t=tris[i], a=t[0], b=t[1], c=t[2];
      var ab=[(a[0]+b[0])/2,(a[1]+b[1])/2], bc=[(b[0]+c[0])/2,(b[1]+c[1])/2], ca=[(c[0]+a[0])/2,(c[1]+a[1])/2];
      next.push([a,ab,ca],[ab,b,bc],[ca,bc,c]);
    }
    tris=next;
  }
  return { value:tris, error:null };
}
function frSvg(kind, order){
  var W=540, H=480, s='<svg xmlns="http://www.w3.org/2000/svg" width="'+W+'" height="'+H+'" viewBox="0 0 '+W+' '+H+'"><rect width="'+W+'" height="'+H+'" fill="#0A0A0B"/>';
  if(kind==='mandelbrot'){
    var g=frMandelGrid(96, 80, 40);
    if(g.error) return g;
    var cw=W/96, ch=H/80;
    for(var y=0;y<80;y++) for(var x=0;x<96;x++){
      var v=g.value[y][x];
      if(v>=40) s+='<rect x="'+(x*cw).toFixed(1)+'" y="'+(y*ch).toFixed(1)+'" width="'+(cw+0.5).toFixed(1)+'" height="'+(ch+0.5).toFixed(1)+'" fill="#5E6AD2"/>';
      else if(v>8) s+='<rect x="'+(x*cw).toFixed(1)+'" y="'+(y*ch).toFixed(1)+'" width="'+(cw+0.5).toFixed(1)+'" height="'+(ch+0.5).toFixed(1)+'" fill="rgba(34,211,238,'+(v/40).toFixed(2)+')"/>';
    }
  } else if(kind==='koch'){
    var k=frKoch(order);
    if(k.error) return k;
    var d='';
    for(var i=0;i<k.value.length;i++){
      var sg=k.value[i];
      d+='M'+sg[0][0].toFixed(1)+' '+sg[0][1].toFixed(1)+'L'+sg[1][0].toFixed(1)+' '+sg[1][1].toFixed(1);
    }
    s+='<path d="'+d+'" stroke="#22D3EE" stroke-width="1.2" fill="none"/>';
  } else if(kind==='sierpinski'){
    var t=frSierpinski(order);
    if(t.error) return t;
    for(var j=0;j<t.value.length;j++){
      var tr=t.value[j];
      s+='<polygon points="'+tr.map(function(p){ return p[0].toFixed(1)+','+p[1].toFixed(1); }).join(' ')+'" fill="none" stroke="#A78BFA" stroke-width="0.8"/>';
    }
  } else return { value:null, error:'未知分形: '+kind };
  return { value:s+'</svg>', error:null };
}
